<template>
  <ion-page>
    <ion-content ref="contentRef" :fullscreen="true">
      <main class="staff-shell"><button v-if="menuOpen" class="staff-scrim" aria-label="Close navigation" @click="menuOpen = false"></button><aside id="staff-sidebar" class="staff-sidebar" :class="{ 'mobile-open': menuOpen }"><BrandMark /><nav @click="menuOpen = false"><p>MY WORKSPACE</p><a class="active" href="#overview" @click.prevent="scrollToSection('overview')"><ion-icon :icon="gridOutline" />Overview</a><a href="#queue" @click.prevent="scrollToSection('queue')"><ion-icon :icon="staff.queueIcon" />{{ staff.queueLabel }}</a><a href="#activity" @click.prevent="scrollToSection('activity')"><ion-icon :icon="listOutline" />Recent activity</a><p>QUICK ACCESS</p><router-link v-if="!isBoarding" to="/staff/ticketing/walk-in"><ion-icon :icon="ticketOutline" />Walk-in ticket</router-link><router-link :to="`/staff/${route.params.role}/settings`"><ion-icon :icon="settingsOutline" />Settings</router-link></nav><button class="logout" type="button" @click="logout"><ion-icon :icon="logOutOutline" />Log out</button></aside><section class="staff-main"><header class="topbar"><button class="staff-menu" :aria-expanded="menuOpen" aria-controls="staff-sidebar" aria-label="Toggle navigation" @click="menuOpen = !menuOpen"><ion-icon :icon="menuOpen ? closeOutline : menuOutline" /></button><div class="breadcrumbs">Staff workspace <ion-icon :icon="chevronForwardOutline" aria-hidden="true" /> <strong>{{ staff.role }}</strong></div><div class="top-actions"><ion-icon :icon="notificationsOutline" /><span class="staff-profile-chip"><span class="staff-profile-icon"><ion-icon :icon="staff.actionIcon" aria-hidden="true" /></span><span class="staff-profile-copy"><strong>{{ staff.name }}</strong><small>{{ staff.role }}</small></span></span></div></header><main id="overview" class="content"><div class="heading"><div><p class="kicker">{{ staff.eyebrow }}</p><h1>{{ staff.greeting }}</h1><p>{{ staff.description }}</p></div><ion-button v-if="isBoarding" class="primary" :disabled="busy" @click="showScanner = true"><ion-icon slot="start" :icon="staff.actionIcon" />{{ staff.action }}</ion-button><button class="staff-refresh" type="button" :disabled="busy" @click="refreshQueues">Refresh</button></div><p v-if="loadError" class="staff-note error" role="alert">{{ loadError }}</p><label v-if="isBoarding" class="sailing-picker">Sailing<select v-model="activeSailing"><option v-for="sailing in activeSailings" :key="sailing.code" :value="sailing.code">{{ sailing.code }} - {{ sailing.origin.name }} to {{ sailing.destination.name }} - {{ new Date(sailing.departureAt).toLocaleString() }}</option></select></label><section class="metric-grid"><article v-for="metric in staff.metrics" :key="metric.label"><span :class="metric.tone"><ion-icon :icon="metric.icon" /></span><div><small>{{ metric.label }}</small><strong>{{ metric.value }}</strong><em>{{ metric.note }}</em></div></article></section><section class="workspace-grid"><article id="queue" class="panel queue-panel"><div class="panel-heading"><div><p class="kicker">{{ staff.queueEyebrow }}</p><h2>{{ staff.queueTitle }}</h2></div><input v-if="!isBoarding" v-model="searchText" class="queue-search" type="search" placeholder="Search reference, passenger, route" aria-label="Search bookings" /><span v-else class="filter">{{ activeSailing || 'No sailing selected' }}</span></div><div class="queue-list"><div v-for="item in queueItems" :key="item.passengerId || item.reference || item.name" class="queue-item"><span class="person-avatar" :class="isBoarding ? item.tone : 'blue'">{{ isBoarding ? item.initials : initialsFor(bookingName(item)) }}</span><div><strong>{{ isBoarding ? item.name : bookingName(item) }}</strong><p>{{ isBoarding ? item.detail : `${item.reference} · ${item.sailing.origin.name} to ${item.sailing.destination.name} · ${new Date(item.sailing.departureAt).toLocaleString()}` }}</p></div><span class="status" :class="itemStatus(item).toLowerCase().replace('_','-').replace(' ','-')">{{ itemStatus(item) }}</span><button class="queue-update" :aria-label="queueActionLabel(item) + ': ' + (isBoarding ? item.name : item.reference)" :title="queueActionLabel(item)" :disabled="isQueueItemComplete(item) || busy" @click="processItem(item)">{{ queueActionLabel(item) }}</button></div><p v-if="!queueItems.length" class="empty-state">{{ searchText ? 'No reservations match your search.' : 'No records found.' }}</p></div></article><aside v-if="isBoarding" class="panel shift-panel"><p class="kicker">SELECTED SAILING</p><h2>{{ activeSailing || 'Choose a sailing' }}</h2><p class="muted">Boarding records and ticket status are read live from the database.</p></aside><aside v-else class="panel shift-panel ticketing-guide"><p class="kicker">AT THE COUNTER</p><h2>Ticketing steps</h2><ol><li>Find the reservation and confirm the passenger details.</li><li>Collect cash, then record payment to issue tickets.</li><li>For a passenger without an account, create a walk-in ticket and print the receipt.</li></ol><router-link to="/staff/ticketing/walk-in" class="walk-in-link"><ion-icon :icon="ticketOutline" /> Issue walk-in ticket</router-link></aside></section><section id="activity" class="panel activity-panel"><div class="panel-heading"><div><p class="kicker">{{ isBoarding ? 'BOARDING ACTIVITY' : 'RECENT RESERVATIONS' }}</p><h2>{{ isBoarding ? 'Activity log' : 'Latest database records' }}</h2></div><span class="activity-count">{{ recentEvents.length }} records</span></div><div class="activity-list"><article v-for="(event, index) in recentEvents" :key="`${event.title}-${index}`" class="activity-item"><span class="activity-icon"><ion-icon :icon="event.icon" aria-hidden="true" /></span><div><strong>{{ event.title }}</strong><p>{{ event.detail }}</p></div><small>{{ event.time }}</small></article><p v-if="!recentEvents.length" class="empty-state">No recent records found.</p></div></section><div class="staff-note"><ion-icon :icon="informationCircleOutline" /><span>Confirm cash payment before issuing tickets. Give walk-in passengers their printed reference and ticket code.</span></div></main></section><ion-modal :is-open="showScanner" @didDismiss="showScanner = false; stopCamera()"><div class="modal-card"><button class="close" aria-label="Close" @click="showScanner = false"><ion-icon :icon="closeOutline" /></button><template><span class="scan-icon"><ion-icon :icon="scanOutline" /></span><p class="kicker">GATE CHECK-IN</p><h2>Scan passenger ticket</h2><p>Enter the ticket code printed on the e-ticket to load its live boarding record.</p><video ref="scannerVideo" class="scanner-video" autoplay playsinline muted></video><button class="camera-action" type="button" @click="startCamera">Scan QR with camera</button><p v-if="scanError" class="scan-error" role="alert">{{ scanError }}</p><label class="modal-field">Ticket code<input v-model="ticketLookup" autocomplete="off" placeholder="Paste ticket code" /></label><ion-button expand="block" class="primary" :disabled="!ticketLookup.trim()" @click="lookupTicket">Find ticket</ion-button></template></div></ion-modal><ion-modal :is-open="!!selectedBooking" @didDismiss="selectedBooking = null"><div class="modal-card ticket-list-modal"><button class="close" aria-label="Close tickets" @click="selectedBooking = null"><ion-icon :icon="closeOutline" /></button><p class="kicker">{{ selectedBooking?.reference }}</p><h2>Booking and payment</h2><p>Amount due: <strong>PHP {{ Number(selectedBooking?.total || 0).toLocaleString() }}</strong> · {{ selectedBooking?.paymentStatus === 'PAID' ? 'Paid' : 'Awaiting payment' }}</p><p>{{ selectedBooking?.sailing.origin.name }} to {{ selectedBooking?.sailing.destination.name }} · {{ new Date(selectedBooking?.sailing.departureAt || Date.now()).toLocaleString() }}</p><article v-for="person in selectedBooking?.bookingPassengers_on_booking || []" :key="person.ticketCode" class="ticket-record"><div><strong>{{ person.fullName }}</strong><small>{{ person.passengerType }} · {{ selectedBooking?.paymentStatus === 'PAID' ? person.ticketStatus : 'Awaiting payment' }}</small></div><code v-if="selectedBooking?.paymentStatus === 'PAID'">{{ person.ticketCode }}</code><small v-else>Ticket issued after payment</small></article><p v-if="loadError" class="scan-error" role="alert">{{ loadError }}</p><p v-if="selectedBooking?.paymentStatus !== 'PAID' && new Date(selectedBooking?.sailing.departureAt || 0) <= new Date()" class="scan-error">This sailing has departed. The booking remains for history; payment cannot be recorded here.</p><div v-if="selectedBooking?.paymentStatus !== 'PAID' && selectedBooking?.status !== 'CANCELLED' && new Date(selectedBooking?.sailing.departureAt || 0) > new Date()" class="payment-actions"><label class="modal-field">Payment method<select v-model="paymentMethod"><option value="CASH">Cash</option></select></label><ion-button expand="block" class="primary" :disabled="busy" @click="collectPayment">{{ busy ? 'Recording…' : 'Record payment and issue tickets' }}</ion-button></div></div></ion-modal></main>
    </ion-content>
  </ion-page>
</template>
<script setup lang="ts">
import { dataConnectRequestError } from '../data/dataConnectErrors'
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { IonButton, IonContent, IonIcon, IonModal, IonPage, onIonViewDidEnter, onIonViewWillEnter } from '@ionic/vue'
import { boatOutline, checkmarkCircle, chevronForwardOutline, closeOutline, gridOutline, informationCircleOutline, listOutline, logOutOutline, menuOutline, notificationsOutline, peopleOutline, scanOutline, searchOutline, settingsOutline, ticketOutline } from 'ionicons/icons'
import BrandMark from '../../components/BrandMark.vue'
import { clearSessionViews } from '../composables/sessionViews'
import { boardingActivity, boardingManifest, boardingSailings, boardTicket, checkInTicket, collectBookingPayment, staffBookings } from '../dataconnect-generated/staff'
import { auth, staffDataConnect } from '../services/firebase'
import { signOut } from 'firebase/auth'
const route = useRoute()
const router = useRouter()
const contentRef = ref<any>(null)
const showScanner = ref(false)
const menuOpen = ref(false)
const busy = ref(false)
const loadError = ref('')
const searchText = ref('')
const ticketLookup = ref('')
const scannerVideo = ref<HTMLVideoElement | null>(null)
const scanError = ref('')
let scannerStream: MediaStream | null = null
let scanFrame = 0
const selectedBooking = ref<any>(null)
const paymentMethod = ref('CASH')
const activeSailing = ref('')
type QueueItem = { passengerId?: string; ticketCode?: string; reference?: string; name: string; initials: string; detail: string; status: string; tone: string }
const ticketingQueue = ref<any[]>([])
const boardingQueue = ref<QueueItem[]>([])
const boardingEvents = ref<any[]>([])
function bookingName(item: any) { return item.bookingChannel === 'WALK_IN' ? item.bookingPassengers_on_booking?.[0]?.fullName || 'Walk-in passenger' : item.owner?.fullName || 'Passenger' }
const recentEvents = computed(() => isBoarding.value ? boardingEvents.value.map(item => ({ title: item.eventType === 'BOARDED' ? 'Passenger boarded' : 'Passenger checked in', detail: `${item.passenger.fullName} · ${item.passenger.booking.reference}`, time: new Date(item.createdAt).toLocaleString(), icon: boatOutline })) : ticketingQueue.value.slice(0, 5).map(item => ({ title: item.status === 'CANCELLED' ? 'Reservation cancelled' : item.paymentStatus === 'PAID' ? 'Payment recorded' : 'Awaiting payment', detail: `${item.reference} · ${bookingName(item)} · ${item.passengerCount} passenger(s)`, time: new Date(item.createdAt).toLocaleString(), icon: ticketOutline })))
const activeSailings = ref<Array<{code:string; status:string; departureAt:string; origin:{name:string}; destination:{name:string}; vessel:{name:string}}>>([])
const sailingReadyToBoard = computed(() => activeSailings.value.find(sailing => sailing.code === activeSailing.value)?.status === 'BOARDING')
const ticketing = { name:'Ticketing Staff',role:'Ticketing Staff',eyebrow:'TICKETING DESK',greeting:'Booking queue',description:'Collect payment for reservations and issue walk-in tickets.',action:'Walk-in ticket',actionIcon:ticketOutline,queueIcon:ticketOutline,queueLabel:'Booking queue',queueEyebrow:'BOOKING QUEUE',queueTitle:'Reservations',metrics:[{label:'Reservations',value:'—',note:'Live records',tone:'blue',icon:ticketOutline},{label:'Paid',value:'—',note:'Ready for sailing',tone:'mint',icon:checkmarkCircle},{label:'Awaiting payment',value:'—',note:'At ticketing desk',tone:'amber',icon:peopleOutline}]}
const boarding = { name:'Boarding Staff',role:'Boarding Staff',eyebrow:'BOARDING DESK',greeting:'Boarding queue',description:'Check in valid tickets and record passengers as they board.',action:'Find ticket',actionIcon:searchOutline,queueIcon:scanOutline,queueLabel:'Boarding queue',queueEyebrow:'LIVE BOARDING',queueTitle:'Passengers on selected sailing',metrics:[{label:'Tickets',value:'—',note:'Sailing manifest',tone:'blue',icon:ticketOutline},{label:'Checked in',value:'—',note:'Gate status',tone:'mint',icon:scanOutline},{label:'Boarded',value:'—',note:'Boarding status',tone:'amber',icon:boatOutline}]}
const isBoarding = computed(() => route.params.role === 'boarding')
const isWorkspaceRoute = computed(() => route.path === '/staff/ticketing' || route.path === '/staff/boarding')
const staff = computed(() => {
 const source = isBoarding.value ? boarding : ticketing
 const items = isBoarding.value ? boardingQueue.value : ticketingQueue.value
 const metrics = isBoarding.value ? [
  {...source.metrics[0],value:String(items.length)},
  {...source.metrics[1],value:String(items.filter(x => x.status === 'CHECKED-IN' || x.status === 'BOARDED').length)},
  {...source.metrics[2],value:String(items.filter(x => x.status === 'BOARDED').length)},
 ] : [
  {...source.metrics[0],value:String(items.length)},
  {...source.metrics[1],value:String(items.filter(x => x.paymentStatus === 'PAID').length)},
  {...source.metrics[2],value:String(items.filter(x => x.paymentStatus !== 'PAID' && x.status !== 'CANCELLED').length)},
 ]
 return {...source,name:auth?.currentUser?.displayName || auth?.currentUser?.email?.split('@')[0] || source.name,metrics}
})
const queueItems = computed(() => isBoarding.value ? boardingQueue.value : ticketingQueue.value.filter(item => `${item.reference} ${bookingName(item)} ${item.bookingChannel} ${item.sailing.origin.name} ${item.sailing.destination.name}`.toLowerCase().includes(searchText.value.toLowerCase().trim())))
watch(() => [route.params.role,activeSailing.value],() => { if (isWorkspaceRoute.value) void refreshQueues() })
onIonViewWillEnter(() => { if (isWorkspaceRoute.value) void refreshQueues() })
onIonViewDidEnter(() => { if (route.hash) void scrollToSection(route.hash.slice(1)) })
let refreshToken = 0
async function refreshQueues() {
 if (!isWorkspaceRoute.value) return
 const requestId = ++refreshToken
 loadError.value = ''
 if (!staffDataConnect) { ticketingQueue.value=[]; boardingQueue.value=[]; loadError.value='Firebase is not configured. Add the Web app settings to .env.local.'; return }
 try {
  if (isBoarding.value) {
   const sailings=await boardingSailings(staffDataConnect,{fetchPolicy:'SERVER_ONLY'})
   if (requestId !== refreshToken) return
   activeSailings.value=sailings.data.sailings.filter(sailing => sailing.status === 'BOARDING' || new Date(sailing.departureAt) > new Date())
   if (!activeSailings.value.some(sailing => sailing.code === activeSailing.value)) activeSailing.value=activeSailings.value[0]?.code || ''
   if (!activeSailing.value) { boardingQueue.value=[]; boardingEvents.value=[]; return }
   const sailingCode = activeSailing.value
   const [result, activity]=await Promise.all([boardingManifest(staffDataConnect,{sailingCode},{fetchPolicy:'SERVER_ONLY'}),boardingActivity(staffDataConnect,{sailingCode},{fetchPolicy:'SERVER_ONLY'})])
   if (requestId !== refreshToken || sailingCode !== activeSailing.value) return
   boardingEvents.value=activity.data.boardingEvents
   boardingQueue.value=result.data.bookings.flatMap(booking=>booking.bookingPassengers_on_booking.map(person=>({
    passengerId:person.id,ticketCode:person.ticketCode,reference:booking.reference,name:person.fullName,
    initials:person.fullName.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase(),
    detail:booking.reference+' - '+sailingCode+' - '+person.passengerType,
    status:person.ticketStatus.replace('_','-'),tone:person.ticketStatus==='BOARDED'?'mint':'blue',
   })))
  } else {
   const result=await staffBookings(staffDataConnect,{fetchPolicy:'SERVER_ONLY'})
   if (requestId !== refreshToken) return
   ticketingQueue.value=result.data.bookings
  }
 } catch(error) { if (requestId === refreshToken) { ticketingQueue.value=[]; boardingQueue.value=[]; loadError.value=dataConnectRequestError(error, 'Could not load operations.') } }
}
function itemStatus(item:QueueItem){if(isBoarding.value)return item.status;const booking=item as any;return booking.status==='CANCELLED'?'CANCELLED':booking.paymentStatus==='PAID'?'PAID':new Date(booking.sailing.departureAt)<=new Date()?'PAST DUE':'AWAITING PAYMENT'}
function isQueueItemComplete(item:QueueItem){return isBoarding.value&&(item.status==='BOARDED'||(item.status==='CHECKED-IN'&&!sailingReadyToBoard.value)||(item.status!=='ISSUED'&&item.status!=='CHECKED-IN'))}
function queueActionLabel(item:QueueItem){return isBoarding.value?(item.status==='ISSUED'?'Check in':item.status==='CHECKED-IN'?(sailingReadyToBoard.value?'Board':'Await boarding'):item.status==='BOARDED'?'Boarded':'Not ready'):'Details'}
async function processItem(item:QueueItem){
 if(!isBoarding.value){selectedBooking.value=item;return}
 if(!item.passengerId||!staffDataConnect||(item.status!=='ISSUED'&&item.status!=='CHECKED-IN'))return
 if(item.status==='CHECKED-IN'&&!sailingReadyToBoard.value){loadError.value='Admin must set this sailing to BOARDING before passengers can board.';return}
 busy.value=true;loadError.value=''
 try {
  if(item.status==='ISSUED')await checkInTicket(staffDataConnect,{passengerId:item.passengerId})
  else await boardTicket(staffDataConnect,{passengerId:item.passengerId})
  await refreshQueues()
 } catch(error){loadError.value=dataConnectRequestError(error, 'Could not update ticket status.')}
 finally{busy.value=false}
}
async function lookupTicket(){const item=boardingQueue.value.find(candidate=>candidate.ticketCode?.toLowerCase()===ticketLookup.value.trim().toLowerCase());if(item){showScanner.value=false;ticketLookup.value='';await processItem(item)}else loadError.value='No ticket with that code was found on the selected sailing.'}
function stopCamera(){if(scanFrame)cancelAnimationFrame(scanFrame);scanFrame=0;scannerStream?.getTracks().forEach(track=>track.stop());scannerStream=null;if(scannerVideo.value)scannerVideo.value.srcObject=null}
async function startCamera(){
 scanError.value=''
 const Detector=(window as any).BarcodeDetector
 if(!Detector){scanError.value='Camera QR scanning is unavailable in this browser. Enter the ticket code instead.';return}
 try{
  stopCamera();await nextTick()
  scannerStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false})
  if(!scannerVideo.value){stopCamera();return}
  scannerVideo.value.srcObject=scannerStream
  await scannerVideo.value.play()
  const detector=new Detector({formats:['qr_code']})
  const scan=async()=>{
   if(!scannerStream||!scannerVideo.value)return
   try{const codes=await detector.detect(scannerVideo.value);if(codes[0]?.rawValue){ticketLookup.value=String(codes[0].rawValue);stopCamera();await lookupTicket();return}}catch{/* Keep scanning until the camera closes. */}
   scanFrame=requestAnimationFrame(scan)
  }
  scanFrame=requestAnimationFrame(scan)
 }catch(error){stopCamera();scanError.value=dataConnectRequestError(error, 'Could not start camera. Enter the ticket code instead.')}
}
onBeforeUnmount(stopCamera)
async function collectPayment(){
 if(!staffDataConnect||!selectedBooking.value||busy.value)return
 if(!window.confirm(`Confirm cash received: PHP ${Number(selectedBooking.value.total).toLocaleString()} for ${selectedBooking.value.reference}?`))return
 busy.value=true;loadError.value=''
 try{await collectBookingPayment(staffDataConnect,{bookingId:selectedBooking.value.id,method:paymentMethod.value});selectedBooking.value=null;await refreshQueues()}
 catch(error){loadError.value=dataConnectRequestError(error, 'Could not record payment.')}
 finally{busy.value=false}
}
function initialsFor(name:string){return name.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase()}
async function scrollToSection(id:string){const content=await contentRef.value?.$el.getScrollElement();const target=document.getElementById(id);if(content&&target)await contentRef.value?.$el.scrollToPoint(0,Math.max(0,target.getBoundingClientRect().top-content.getBoundingClientRect().top+content.scrollTop),350)}
async function logout(){if(auth)await signOut(auth);await router.replace('/login');clearSessionViews()}
</script>
<style scoped>
